(function(){
 const by=id=>ST.find(s=>s.id===id);
 by('materia').alert='La lectura desarrollada se ha contrastado con el original francés. El archivo español contiene traducciones defectuosas y no se utiliza aquí como fuente de citas literales.';
 by('materia').meta=['Capítulo I · con conexiones a II–III','Percepción, cuerpo y memoria'];
 by('materia').guide=[['Cap. I · comienzo','Partir del campo de imágenes','Reconstruye el estatuto del cuerpo dentro del mundo de imágenes y el argumento que impide convertir una parte en explicación inmediata del todo.',4],['Cap. I · percepción','Seleccionar para actuar','Distingue selección práctica, decisión consciente y percepción pura. No presentes el límite de análisis como una experiencia ordinaria sin memoria.',10],['Caps. II–III · reconocimiento','Hábito, recuerdo y atención','Contrasta la ejecución de una lección aprendida con el recuerdo de una ocasión singular. Explica cómo el reconocimiento articula percepción y pasado.',0,'matiereFR']];
 by('riemann').concepts[2]=['Curvatura intrínseca','Invariante geométrico que no desaparece por un simple cambio de coordenadas. Una fórmula métrica variable en una dimensión no prueba curvatura.'];
 by('riemann').guide[1][2]='Bajo las hipótesis que Riemann examina, el cuadrado del elemento de longitud se expresa mediante una forma cuadrática. Distingue coeficientes, coordenadas y curvatura intrínseca.';
 by('opcional').idea='Leibniz y El pliegue ofrecen un contrapunto: expresar un mundo, elegir entre posibles y producir diferencias no son operaciones equivalentes.';
 by('opcional').meta=['Contrapunto conceptual','Posibilidad, expresión y pliegue'];
 by('opcional').alert='Lee estas fuentes para introducir una dificultad precisa. El vocabulario compartido de infinito o multiplicidad no demuestra una misma teoría de la creación.';
 by('opcional').guide=[['La evolución creadora · cap. I','La espera del azúcar','Reconstruye la diferencia entre vivir un proceso y representarlo como una serie terminada. No deduzcas que medir carece de validez.',0,'evol'],['Monadología · §§ 1–18 y 53–62','Percepción, mundos y perspectivas','Distingue simplicidad y variedad perceptiva. Después relaciona elección de mundos y expresión de un universo desde perspectivas diferentes.',9,'mona'],['El pliegue · cap. I','La función operatoria','Explica qué hacen los dos pisos: repliegues de la materia y pliegues en el alma. Evita usar pliegue como sinónimo general de complejidad.',11,'pliegue']];
 const questions={
 capV:[['¿Por qué el capítulo V necesita distinguir división reflexiva y genética?','La primera separa tendencias en una experiencia mixta; la segunda explica cómo una virtualidad produce líneas divergentes. Analizar productos no basta para explicar su génesis.'],['¿Qué oculta el posible retrospectivo?','Usa la forma del resultado para fabricar un antecedente semejante y deja sin explicar la invención de esa forma y de sus líneas de producción.'],['¿Qué limita la comparación con Lezama?','La afinidad contra la preformación no identifica virtual y potens. Debe conservarse la articulación lezamiana de causalidad, encarnación y resurrección.']],
 capII:[['¿Cómo puede una multiplicidad ser continua y heterogénea?','La continuidad no exige unidades iguales. En la duración, lo anterior modifica lo siguiente y la división transforma cualitativamente la experiencia.'],['¿Por qué el espacio no pertenece simplemente a lo discreto?','Una extensión geométrica puede ser continua y mensurable. Riemann no distribuye espacio y duración entre discreto y continuo.'],['¿Analizar un sentimiento necesariamente lo falsifica?','No. Debemos describir qué cambia al distinguir sus componentes, sin imponer el modelo de piezas exteriores previamente separadas.']],
 preludio:[['¿Qué diferencia vivencia oblicua y súbito?','La primera desplaza y aproxima relaciones indirectas; el segundo concentra una inteligibilidad que reorganiza lo acumulado. El ensayo articula su intercambio.'],['¿Por qué el retorno del acto sobre el germen importa?','Impide reducir el proceso a desarrollo lineal: lo producido interviene sobre sus condiciones y abre otra extensión.'],['¿Qué objeción introduce la resurrección?','Puede interpretarse como finalidad previa. La tesis debe explicar cómo se relacionan esa orientación y la apertura de las realizaciones concretas.']],
 paradiso:[['¿Qué detalles sostienen una transformación del retorno?','El tintineo, el cambio de registro de la voz, la pérdida de la respuesta viva del maestro y la apertura de una tarea para Cemí.'],['¿Por qué una voz evocada no es el recuerdo puro?','Ya tiene forma sensible y función en una experiencia narrada. El recuerdo puro designa otro estatuto, anterior a la actualización psicológica.'],['¿Qué lectura alternativa debe afrontar la hipótesis de apertura?','Que la voz del maestro se convierta en autoridad interior. El final propone una continuación, pero no muestra su cumplimiento futuro.']],
 materia:[['¿Qué diferencia imagen bergsoniana e imagen poética?','La primera organiza el problema de materia, percepción y acción; la segunda debe reconstruirse dentro de la poética de Lezama. La palabra compartida no basta.'],['¿Por qué la percepción pura es un límite?','Separa analíticamente la relación presente con las cosas de la memoria. La percepción ordinaria las articula.'],['¿Saber una lección equivale a recordar cuándo la aprendí?','No. Una habilidad adquirida y la evocación de un episodio singular cumplen funciones diferentes, aunque colaboren.']],
 riemann:[['¿El conteo determina una única distancia entre elementos?','No. El pasaje sobre lo discreto trata cantidades de elementos, no una unicidad general de funciones métricas sobre conjuntos discretos.'],['¿Una métrica variable en una dimensión prueba curvatura?','No. Puede reescribirse mediante la coordenada de longitud acumulada. El experimento compara longitudes manteniendo la identificación del intervalo.'],['¿Qué significa que la medida venga de fuera?','Que la mera noción de continuo no determina su métrica. No exige imaginar un agente situado espacialmente fuera del universo.']],
 critica:[['¿Qué tres preguntas hay que separar?','Influencia histórica, fidelidad matemática y productividad filosófica. Cada una requiere pruebas diferentes.'],['¿Qué cambia la objeción histórica de Widder?','Obliga a atribuir a Deleuze la lectura de Bergson mediante Riemann, sin dar por documentada una influencia directa sobre Bergson.'],['¿Qué aporta la mediación de Weyl reconstruida por Calamari?','Sitúa la referencia en un canal de recepción posterior y evita tratarla como transmisión intacta desde 1854.']],
 opcional:[['¿Una mónada simple carece de variedad?','No. La percepción expresa multiplicidad en la unidad y la apetición se refiere al paso entre percepciones.'],['¿Por qué los posibles de Leibniz no son un menú de objetos?','La discusión concierne a mundos, su conveniencia y su articulación de conjunto, no a combinaciones arbitrarias de piezas independientes.'],['¿Qué debería demostrar una lectura del pliegue en Lezama?','Una operación textual concreta y la ventaja explicativa del concepto. La complejidad o el ornamento no bastan.']],
 memoria:[['¿Las secciones del cono guardan épocas diferentes?','No. Cada nivel comprende todo el pasado bajo un grado de contracción; cambian organización y relieve, no solamente fecha de los contenidos.'],['¿Contemporaneidad del pasado y presente significa que todo ocurre a la vez?','No. Distingue dimensiones de la temporalización, no simultaneidad cronológica de todos los acontecimientos.'],['¿La distinción entre conservación y acceso prueba conservación integral?','No por sí sola. Explica por qué no actualizar un recuerdo no equivale lógicamente a su inexistencia, pero la tesis ontológica exige más argumento.']],
 duraciones:[['¿Tiempo único significa ritmo uniforme?','No en la reconstrucción de Deleuze. La unidad busca dar cuenta de una multiplicidad virtual con diferencias de contracción y distensión.'],['¿Qué aporta el ejemplo de los flujos?','Pregunta por la duración que permite experimentarlos juntos y por el desdoblamiento de la atención que los abarca.'],['¿Las secuencias de una novela prueban pluralidad ontológica de tiempos?','No. Primero hay que describir relaciones narrativas; la conclusión ontológica necesitaría otro argumento.']],
 emocion:[['¿Qué diferencia las dos emociones?','Una sigue a una representación; la otra puede engendrar representaciones e ideas. La distinción no es solo de intensidad.'],['¿Qué admite y qué jerarquiza la nota 36?','Admite dos fuentes del arte y proporciones variables, pero atribuye a la novela sobre todo fabulación. La modalización no borra esa valoración.'],['¿Cómo evaluar una transmisión creadora en Paradiso?','Analizando qué capacidades abre la escena y afrontando la alternativa de una autoridad interiorizada, sin asegurar un futuro que el final no narra.']],
 taller:[['¿Qué comparten los dos pasajes centrales de la tesis propuesta?','Permiten cuestionar que crear sea ejecutar una forma prefijada. La comparación identifica esa afinidad operativa, no una identidad de sistemas.'],['¿Qué hace la objeción sobre la resurrección?','Obliga a distinguir orientación y preformación y a mantener una divergencia entre los horizontes de ambos autores.'],['¿Cuándo ayuda Riemann a la ponencia?','Cuando una distinción matemática precisa es necesaria para el argumento y su traslado se justifica. No demuestra por sí sola una tesis literaria.']]
 };
 Object.keys(questions).forEach(id=>{by(id).quiz=questions[id];});
})();
